declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\ValueObject\Holder\UserMfaRecoveryCodeUsedAtAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserMfaRecoveryCodeUsedAtAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserMfaRecoveryCodeUsedAtAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getUsedAt returns null on a freshly created holder.
     */
    public function testUsedAtNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserMfaRecoveryCodeUsedAtAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isUsedAtAssigned());
        $this->assertNull($holder->getUsedAt());
    }
}
class ImplWithUserMfaRecoveryCodeUsedAtAttributeHolderUnitTest
{
    use UserMfaRecoveryCodeUsedAtAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedUsedAtRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultUsedAt();
    }
}
